create table if not exists business_settings(id bigint generated by default as identity primary key,name_ar text not null,name_en text,vat_number text,address text,vat_rate numeric not null default 15);create table if not exists profiles(id uuid primary key,display_name text not null,role text not null check(role in('admin','cashier')));create table if not exists products(id bigint generated by default as identity primary key,name_ar text not null,name_en text,category text,price numeric(12,2) not null,active boolean default true);create table if not exists shifts(id bigint generated by default as identity primary key,cashier_id uuid,opened_at timestamptz default now(),closed_at timestamptz,opening_cash numeric(12,2) default 0,closing_cash numeric(12,2));create table if not exists sales(id bigint generated by default as identity primary key,invoice_no text unique not null,shift_id bigint references shifts(id),cashier_id uuid,subtotal numeric(12,2) not null,vat numeric(12,2) not null,total numeric(12,2) not null,payment_method text not null check(payment_method in('cash','card')),status text not null default 'paid',created_at timestamptz default now());create table if not exists sale_items(id bigint generated by default as identity primary key,sale_id bigint references sales(id) on delete cascade,product_id bigint references products(id),name_ar text,name_en text,qty numeric not null,unit_price numeric(12,2) not null,line_total numeric(12,2) not null);